<?php declare(strict_types=1); require_once __DIR__.'/../includes/bootstrap.php'; $seed=require __DIR__.'/lessons-html.php'; $course=$db->query("SELECT id FROM learning_courses WHERE slug='html' LIMIT 1")->fetch(PDO::FETCH_ASSOC); if(!$course){$course=$db->query("SELECT id FROM learning_courses WHERE slug='html-for-beginners' LIMIT 1")->fetch(PDO::FETCH_ASSOC);} if(!$course){http_response_code(404);exit('HTML course not found.');} $q=$db->prepare("INSERT INTO learning_lessons (course_id,title,slug,content_html,enabled,sort_order) VALUES (?,?,?,?,1,?) ON DUPLICATE KEY UPDATE title=VALUES(title),content_html=VALUES(content_html),enabled=1,sort_order=VALUES(sort_order)"); foreach($seed as $i=>$lesson){$q->execute([(int)$course['id'],$lesson['title'],$lesson['slug'],$lesson['content_html'],$i+1]);} echo 'Seeded '.count($seed).' HTML lessons.';